<?php session_start(); require 'config/database.php'; require 'lib_security.php'; if(!isset($_SESSION['user'])||$_SESSION['user']['role']!=='admin'){header('Location: login.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['delete'])){verifyCsrf();$pdo->prepare('DELETE FROM notices WHERE id=?')->execute([(int)$_POST['delete']]);header('Location: notices.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){ verifyCsrf();$pdo->prepare('INSERT INTO notices(title,body,audience) VALUES(?,?,?)')->execute([trim($_POST['title']),trim($_POST['body']),$_POST['audience']]);header('Location: notices.php');exit;}
$rows=$pdo->query('SELECT * FROM notices ORDER BY published_at DESC')->fetchAll();$pageTitle='Notices';require'includes/header.php';?>
<div class="container py-4"><div class="d-flex justify-content-between"><h2>Notices</h2><a href="admin.php" class="btn btn-outline-secondary">Dashboard</a></div><div class="card shadow-sm my-3"><div class="card-body"><form method="post"><?php echo csrfField(); ?><div class="row g-2"><div class="col-md-5"><input name="title" class="form-control" placeholder="Notice title" required></div><div class="col-md-3"><select name="audience" class="form-select"><option value="all">All</option><option value="hssc">HSSC</option><option value="bs">BS</option><option value="adp">ADP</option><option value="students">Students</option><option value="teachers">Teachers</option></select></div><div class="col-12"><textarea name="body" class="form-control" rows="4" placeholder="Notice details" required></textarea></div><div class="col-12"><button class="btn btn-primary">Publish Notice</button></div></div></form></div></div><div class="row g-3"><?php foreach($rows as $r):?><div class="col-md-6"><div class="card shadow-sm h-100"><div class="card-body"><div class="d-flex justify-content-between"><h5><?=htmlspecialchars($r['title'])?></h5><form method="post" class="d-inline" onsubmit="return confirm('Delete notice?')"><?php echo csrfField(); ?><button name="delete" value="<?=$r['id']?>" class="btn btn-link text-danger p-0">Delete</button></form></div><small class="text-muted"><?=strtoupper($r['audience'])?> · <?=htmlspecialchars($r['published_at'])?></small><p class="mt-3 mb-0"><?=nl2br(htmlspecialchars($r['body']))?></p></div></div></div><?php endforeach;?></div></div><?php require'includes/footer.php';?>
